from bookings import Booking, load_bookings, ROWS
from ordering import ranked_codes


def test_nine_before_ten():
    assert ranked_codes([Booking("a", 10), Booking("b", 9)]) == ["9", "10"]


def test_mixed_lengths():
    assert ranked_codes([Booking("a", 100), Booking("b", 25), Booking("c", 9), Booking("d", 1000)]) == ["9", "25", "100", "1000"]


def test_stored():
    assert ranked_codes(list(load_bookings())) == [str(v) for v in sorted(v for _, v in ROWS)]


def test_codes_are_text():
    assert all(isinstance(c, str) for c in ranked_codes(list(load_bookings())))


def test_empty():
    assert ranked_codes([]) == []

